        return out("the table — nineteen rows, one per verse: the grades %s; %d on the tape by kind and first verse, %d in the kin's cells by CALL, %d SUPPLIED as laws (four with their writes); the pointer row 13:18; no hole, no open row, no stretch, no state row, no retrograde row" % (dict(sorted(RB_GRADES.items())), sum(1 for r in READBACK if r['tape_kind']), sum(1 for r in READBACK if r['cell']), sum(1 for r in READBACK if r['grade'] == 'SUPPLIED')), ['accepted'])
